  3840→        if (!cmdFiltered.length) {
  3841→            res.innerHTML = '<div id="cmdEmpty"><i class="bi bi-search"></i>Tidak ada hasil untuk "<strong>' + q + '</strong>"</div>';
  3842→            return;
