  3901→        input.addEventListener('keydown', e => {
  3902→            const items = document.querySelectorAll('#cmdResults .cmd-item');
  3903→            if (e.key === 'ArrowDown') { e.preventDefault(); setActive(Math.min(cmdActive + 1, items.length - 1)); }
  3904→            else if (e.key === 'ArrowUp') { e.preventDefault(); setActive(Math.max(cmdActive - 1, 0)); }
  3905→            else if (e.key === 'Enter') {
  3906→                e.preventDefault();
  3907→                if (cmdActive >= 0 && items[cmdActive]) { items[cmdActive].click(); }
  3908→                else if (cmdFiltered[0]) { window.location.href = cmdFiltered[0].href; }
  3909→            }
  3910→        });
