  3959→        } catch(e) {}
  3960→    });
  3961→    // Remove oversized SVGs injected by extensions (width > 24px is suspicious in pagination)
  3962→    document.querySelectorAll('#paginationLinks svg, .pagination svg').forEach(s => {
  3963→        try {
  3964→            const w = parseFloat(s.getAttribute('width') || '0');
  3965→            const h = parseFloat(s.getAttribute('height') || '0');
  3966→            if ((w > 24 || h > 24) && !s.closest('.bi')) s.remove();
  3967→        } catch(e) {}
  3968→    });
  3969→}
  3970→document.addEventListener('DOMContentLoaded', function() {
  3971→    removeKnownChevrons();
  3972→    document.querySelectorAll('#paginationLinks, .pagination, nav.d-flex').forEach(el => {
  3973→        if (el) new MutationObserver(removeKnownChevrons).observe(el, { childList:true, subtree:true });
