// ---- COUNT-UP ANIMATION (manual + auto-detect numeric .stat-value) ----
document.addEventListener('DOMContentLoaded', function() {
    // Auto-detect numeric .stat-value elements and mark them for count-up
    document.querySelectorAll('.stat-value:not(.count-up):not(.no-countup)').forEach(function(el) {
        const raw = el.textContent.trim().replace(/[.,\s]/g, '');
        const num = parseInt(raw, 10);
        // Only animate pure integers between 1 and 999999
        if (!isNaN(num) && num > 0 && num <= 999999 && /^\d+$/.test(raw)) {
            el.setAttribute('data-target', num);
            el.setAttribute('data-original', el.textContent.trim());
            el.classList.add('count-up');
            el.textContent = '0';
        }
    });

    function runCountUp(el) {
        const target = parseInt(el.getAttribute('data-target'), 10);
        if (isNaN(target) || el.hasAttribute('data-counted')) return;
        el.setAttribute('data-counted', '1');
        const duration = 800;
        const step = 14;
        const increment = target / (duration / step);
        let current = 0;
        const timer = setInterval(function() {
            current += increment;
            if (current >= target) { current = target; clearInterval(timer); }
            el.textContent = Math.floor(current).toLocaleString('id-ID');
        }, step);
    }

    const countEls = document.querySelectorAll('.count-up[data-target]');
    if (!countEls.length) return;
    const io2 = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
            if (!entry.isIntersecting) return;
            runCountUp(entry.target);
            io2.unobserve(entry.target);
        });
    }, { threshold: 0.2 });
    countEls.forEach(function(el) { io2.observe(el); });
});

